using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Runtime.InteropServices;
using System.Threading;
using System.Windows.Forms;
using MC2Pack;
namespace Astera {
sealed partial class LibraryForm {
    [StructLayout(LayoutKind.Sequential)]struct CaretThread {internal int Size,Flags;internal IntPtr Active,Focus,Capture,Menu,Moving,Caret;internal int Left,Top,Right,Bottom;}
    [DllImport("user32.dll")]static extern bool GetGUIThreadInfo(uint thread,ref CaretThread info);
    [DllImport("kernel32.dll")]static extern uint GetCurrentThreadId();
    static bool CaretVisible(){var info=new CaretThread{Size=Marshal.SizeOf(typeof(CaretThread))};if(!GetGUIThreadInfo(GetCurrentThreadId(),ref info))throw new IOException("Cannot inspect own caret state");return (info.Flags&1)!=0;}
    internal static int AuditDisplayPolish(string root,bool live){bool effects=UiEffects.Enabled;try{
        if(Directory.Exists(root))throw new IOException("Use a fresh display audit");Directory.CreateDirectory(root);var checks=new List<string>();
        string a="https://tr.rbxcdn.com/first.png",b="https://tr.rbxcdn.com/second.png";string json="{\"data\":[{\"universeId\":42,\"thumbnails\":[{\"state\":\"Blocked\",\"imageUrl\":\"https://tr.rbxcdn.com/blocked.png\"},{\"state\":\"Pending\",\"imageUrl\":\"https://tr.rbxcdn.com/pending.png\"},{\"state\":\"Completed\",\"imageUrl\":\"https://tr.rbxcdn.com/768/432/UnapprovedImage/Png/noFilter\"},{\"state\":\"Completed\",\"imageUrl\":\""+a+"\"},{\"state\":\"Completed\",\"imageUrl\":\""+a+"\"},{\"state\":\"Completed\",\"imageUrl\":\""+b+"\"},{\"state\":\"Completed\",\"imageUrl\":\"https://evil.example/art.png\"}]},{\"universeId\":99,\"thumbnails\":[{\"state\":\"Completed\",\"imageUrl\":\"https://tr.rbxcdn.com/wrong-game.png\"}]}]}";
        var gallery=RobloxSupport.Gallery(Engine.Json.DeserializeObject(json),42);AuditAssert(gallery.SequenceEqual(new[]{a,b}),"Gallery accepted a blocked, duplicate, untrusted or unrelated thumbnail");checks.Add("Roblox gallery skips blocked/pending/placeholder entries, deduplicates valid images and checks the requested universe");
        Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);var store=new Store(Path.Combine(root,"state"));store.Settings.CheckOnStart=false;store.Settings.KeepInTray=false;store.Settings.UseMinecraftSkin=false;store.Settings.AnimatedEffects=true;
        var game=new CustomGame{Name="Roblox gallery fixture",Platform="roblox",PlatformId=live?"14608970270":"1818",Executable=RobloxSupport.WebUrl(live?14608970270:1818),RobloxArtworkVersion=2};
        if(live){var info=RobloxSupport.Lookup(14608970270,CancellationToken.None);game.UniverseId=info.UniverseId;game.Name=info.Name;game.RobloxBanners=info.Banners.Select(url=>RobloxSupport.CacheGallery(url,Path.Combine(root,"gallery"),info.UniverseId,CancellationToken.None)).Where(p=>p!=null).ToArray();AuditAssert(game.RobloxBanners.Length>=2,"Actual experience gallery has fewer than two usable images");checks.Add("Outcome Memories public gallery supplies multiple completed thumbnails without authentication");}
        else{game.RobloxBanners=new[]{Path.Combine(root,"red.png"),Path.Combine(root,"blue.png")};for(int i=0;i<2;i++)using(var image=new Bitmap(768,432)){using(var g=Graphics.FromImage(image))g.Clear(i==0?Color.DarkRed:Color.DarkBlue);image.Save(game.RobloxBanners[i]);}}
        store.Settings.CustomGames.Add(game);store.Save();AuditAssert(new Store(store.Root).Settings.CustomGames[0].RobloxBanners.Length==game.RobloxBanners.Length,"Gallery paths did not persist");checks.Add("Validated gallery paths persist for offline reuse");
        using(var form=new LibraryForm(store,new Channel(),true))using(var clock=new System.Windows.Forms.Timer{Interval=100}){
            form.TopMost=true;form.StartPosition=FormStartPosition.Manual;form.Location=Screen.PrimaryScreen.WorkingArea.Location;form.ReloadGames(game);int ticks=0,code=1;string notes=null;
            clock.Tick+=delegate{try{
                ticks++;var body=form.notes.Controls.OfType<TextBox>().Single();if(ticks<=12){AuditAssert(body.Focused&&body.ReadOnly&&!CaretVisible(),"Read-only notes exposed a blinking editing caret");if(ticks==3){AuditListMessage(body.Handle,0x201,new IntPtr(1),new IntPtr((8<<16)|20));AuditListMessage(body.Handle,0x202,IntPtr.Zero,new IntPtr((8<<16)|20));}return;}
                clock.Stop();body.Select(0,Math.Min(5,body.TextLength));AuditAssert(body.SelectedText==body.Text.Substring(0,body.SelectionLength),"Native notes text selection broke");string text=body.Text;AuditListMessage(body.Handle,0x102,new IntPtr('x'),IntPtr.Zero);AuditAssert(body.Text==text&&!CaretVisible(),"Read-only text accepted typing or exposed a caret");checks.Add("Read-only notes hide the caret through focus, mouse clicks and typing while preserving native text selection");form.librarySearch.Focus();AuditListMessage(form.librarySearch.Handle,0x102,new IntPtr('z'),IntPtr.Zero);AuditAssert(form.librarySearch.Text.Contains("z"),"Editable search input stopped accepting typing");form.librarySearch.Clear();checks.Add("Normal editable search fields still accept keyboard input");
                AuditAssert(form.robloxSlideClock.Interval==12000&&form.robloxSlideClock.Enabled,"Gallery slideshow did not start at a 12-second interval");string first=form.AutomaticGameBackground(game);Application.DoEvents();form.Refresh();Application.DoEvents();long firstPixels;using(var sample=CaptureLibrary(form.banner,new Rectangle(form.banner.Width*3/4,form.banner.Height/3,32,32)))firstPixels=PixelStamp(sample);form.CaptureVisibleUi(root,"gallery-first");form.AdvanceRobloxSlide();string second=form.AutomaticGameBackground(game);AuditAssert(first!=second&&form.notes.Text==notes,"Slide failed to change or rewrote update notes");AuditAssert(form.heroSubtitle.Text=="Open this experience in Roblox."&&form.installationPath.Text.Contains("Managed by Roblox"),"Slide changed Roblox page details");Application.DoEvents();form.Refresh();Application.DoEvents();using(var sample=CaptureLibrary(form.banner,new Rectangle(form.banner.Width*3/4,form.banner.Height/3,32,32)))AuditAssert(PixelStamp(sample)!=firstPixels,"The selected gallery path changed without updating displayed pixels");form.CaptureVisibleUi(root,"gallery-second");checks.Add("Gallery cycles usable backgrounds every 12 seconds without changing notes or game selection");
                UiEffects.Enabled=false;AuditAssert(!form.robloxSlideClock.Enabled,"Effects off did not pause slideshow");UiEffects.Enabled=true;form.Hide();AuditAssert(!form.robloxSlideClock.Enabled,"Hidden window kept slideshow running");form.Show();game.Background=first;form.RefreshView();AuditAssert(!form.robloxSlideClock.Enabled&&form.artLabel.Text==Path.GetFileName(first),"Custom background did not pause automatic gallery");game.Background="";form.RefreshView();form.GameKind=0;AuditAssert(!form.robloxSlideClock.Enabled,"Switching games kept Roblox slideshow running");checks.Add("Slideshow pauses for disabled effects, hidden windows, custom artwork and another selected game");
                File.WriteAllText(Path.Combine(root,"result.json"),Engine.Json.Serialize(new{Passed=true,Checks=checks,LiveMetadata=live,RobloxLaunched=false,LivePreferencesChanged=false,GalleryImages=game.RobloxBanners.Length}));code=0;form.Close();
            }catch(Exception error){clock.Stop();File.WriteAllText(Path.Combine(root,"failure.txt"),error.ToString());form.Close();}};
            form.Shown+=delegate{notes=form.notes.Text;form.notes.Controls.OfType<TextBox>().Single().Focus();clock.Start();};Application.Run(form);return code;
        }
    }catch(Exception error){Directory.CreateDirectory(root);File.WriteAllText(Path.Combine(root,"failure.txt"),error.ToString());return 1;}finally{UiEffects.Enabled=effects;}}
}
}
